async def act(page):
    import re
    # We're already on the Orders page. Perform only the new actions needed from current UI state.

    # Best-effort close of any blocking popup (common on this page). Non-fatal.
    try:
        close_btns = page.get_by_role("button", name=re.compile(r"^(close|×|x|dismiss)$", re.I))
        if await close_btns.count() > 0:
            await close_btns.first.click()
            await page.wait_for_timeout(300)
    except Exception:
        pass

    # 1) Locate the filter row that contains the 'Any' cell (the row with the filter controls)
    filter_row = page.get_by_role("row").filter(has=page.get_by_role("cell", name="Any")).first

    # 2) Within that filter row, find the combobox whose options include 'Canceled'
    target_cb = None
    target_label = None
    try:
        cbs = filter_row.get_by_role("combobox")
        for i in range(await cbs.count()):
            cb = cbs.nth(i)
            opts = cb.get_by_role("option")
            # defensive: iterate options to find the Cancel option by visible text
            for j in range(await opts.count()):
                txt = (await opts.nth(j).inner_text() or "").strip()
                if "cancel" in txt.lower():
                    target_cb = cb
                    target_label = txt
                    break
            if target_cb:
                break
    except Exception:
        target_cb = None
        target_label = None

    if not target_cb:
        # Could not find the status combobox inside the filter row
        print("")
        return

    # 3) Select the 'Canceled' option. Prefer selecting by exact visible label to handle NBSP/whitespace.
    try:
        await target_cb.select_option(label=target_label)
    except Exception:
        # fallback: try selecting by value attribute of the matched option
        opts = target_cb.get_by_role("option")
        for j in range(await opts.count()):
            opt = opts.nth(j)
            txt = (await opt.inner_text() or "").strip()
            if "cancel" in txt.lower():
                val = await opt.get_attribute("value")
                if val is not None:
                    await target_cb.select_option(value=val)
                break

    # 4) Click the Search button scoped to the controls row (the row that contains the "Reset Filter Search" cell)
    try:
        controls_row = page.get_by_role("row").filter(has=page.get_by_role("cell", name="Reset Filter Search")).first
        await controls_row.get_by_role("button", name="Search").click()
    except Exception:
        # fallback to page-level Search button
        try:
            await page.get_by_role("button", name="Search").first.click()
        except Exception:
            print("")
            return

    # 5) Wait for results to refresh
    await page.wait_for_timeout(900)

    # 6) Locate the first Status cell containing 'cancel' (case-insensitive) and scope its parent row
    status_cells = page.get_by_role("cell", name=re.compile(r"cancel", re.I))
    if await status_cells.count() == 0:
        # No canceled orders found
        print("")
        return

    canceled_row = page.get_by_role("row").filter(has=status_cells.first).first

    # 7) Extract the Bill to Name cell (commonly the 5th cell, index 4)
    cells = canceled_row.get_by_role("cell")
    total = await cells.count()

    customer_name = ""
    if total > 4:
        try:
            customer_name = ((await cells.nth(4).inner_text()) or "").strip()
        except Exception:
            customer_name = ""

    # 8) Fallback heuristics if expected cell is empty: choose a cell that looks like a person name
    if not customer_name:
        for i in range(total):
            txt = ((await cells.nth(i).inner_text()) or "").strip()
            if not txt:
                continue
            if re.search(r"cancel", txt, re.I):
                continue
            # skip numeric/currency-only cells
            if re.fullmatch(r"[\d\s,.$€£¥%\-]+", txt):
                continue
            if any(c.isalpha() for c in txt) and " " in txt:
                customer_name = txt
                break
        if not customer_name and total > 0:
            for i in range(total):
                txt = ((await cells.nth(i).inner_text()) or "").strip()
                if txt and not re.search(r"cancel", txt, re.I):
                    customer_name = txt
                    break

    # Print the exact discovered customer name (or empty string)
    print(customer_name)
    return total

